import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import {
  StatCard,
  StatusDot,
  Badge,
  fmtMoney,
  timeAgo,
} from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { DeployButton } from "@/components/customer/DeployButton";
import { humanizeAction, actionDotColor } from "@/components/customer/humanize";
import OnboardingChecklist from "@/components/customer/OnboardingChecklist";
import { getOnboardingSteps } from "@/lib/actions-onboarding";
import { renewalCharge } from "@/lib/renewal-charge";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { annualDiscountPct } from "@/lib/annual-discount";
import { taxContextForUser } from "@/lib/tax";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";

export const dynamic = "force-dynamic";

const icons = {
  servers: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
      <rect x="3" y="4" width="18" height="7" rx="2" />
      <rect x="3" y="13" width="18" height="7" rx="2" />
      <circle cx="7" cy="7.5" r="0.6" fill="currentColor" />
      <circle cx="7" cy="16.5" r="0.6" fill="currentColor" />
    </svg>
  ),
  running: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
      <circle cx="12" cy="12" r="9" />
      <path d="m10 8 6 4-6 4V8Z" fill="currentColor" stroke="none" />
    </svg>
  ),
  spend: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
      <path d="M12 2v20M17 6.5c0-1.9-2.2-3-5-3s-5 1.1-5 3 2 2.7 5 3.3 5 1.5 5 3.4-2.2 3-5 3-5-1.1-5-3" />
    </svg>
  ),
  wallet: (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6">
      <rect x="3" y="6" width="18" height="13" rx="2" />
      <path d="M3 10h18" />
    </svg>
  ),
};

export default async function DashboardPage() {
  const user = await requireUser();
  const [servers, auditLogs, transactions] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id },
      // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs; without
      // them the spend tile could only reach for `plan.priceCents`, which is a
      // different number for both.
      include: { plan: true, osTemplate: true, gamePlan: true, dedicatedIp: true },
      orderBy: { createdAt: "desc" },
    }),
    db.auditLog.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 8,
    }),
    db.walletTransaction.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  const running = servers.filter((s) => s.status === "RUNNING").length;

  // "Monthly spend" is priced through `renewalCharge` — the single function
  // worker/billing.ts, the saved-card path and the "Renew now" button all charge
  // through (lib/renewal-charge.ts). It used to sum `plan.priceCents`, which is
  // a SECOND formula and a different number: it billed a $4.99 game server at
  // its $8.99 base VPS plan, and counted nothing at all for purchased extra disk
  // or a dedicated IP that the customer really does pay for every cycle.
  const paid = servers.filter((s) => !s.isFree && s.status !== "DELETING");
  // VAT/GST for this customer (Finding 1), so the "Monthly spend" figure is
  // tax-inclusive and matches what actually gets charged.
  const spendTaxRatePercent = (await taxContextForUser(user)).ratePercent;
  const spendPrices =
    paid.length > 0
      ? {
          ipMonthlyCents: await dedicatedIpMonthlyCents(),
          extraDiskPerGbCents: await extraDiskPerGbCents(),
          backupPlusCents: await backupPlusMonthlyCents(),
          annualDiscountPct: await annualDiscountPct(),
          taxRatePercent: spendTaxRatePercent,
        }
      // No paid servers -> renewalCharge is never called; the shipped default just
      // satisfies the required field.
      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent: spendTaxRatePercent };
  // A term total divided by the months it buys — a presentation of the
  // authoritative figure, never a re-derivation of it.
  const monthlySpendCents = paid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
  }, 0);
  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  return (
    <div className="space-y-6">
      <OnboardingChecklist steps={await getOnboardingSteps()} />
      {transitional && <AutoRefresh />}
      <PortalHero variant="dashboard" title="Dashboard" sub={`Welcome back, ${user.name.split(" ")[0]}.`}>
        <DeployButton href="/dashboard/deploy">Deploy server</DeployButton>
      </PortalHero>

      {servers.length === 0 ? (
        <div className="card relative overflow-hidden py-16 text-center">
          <div
            className="pointer-events-none absolute inset-0"
            style={{
              background:
                "radial-gradient(ellipse 60% 60% at 50% 0%, rgb(111 71 245 / 0.15), transparent)",
            }}
          />
          <div className="relative">
            <div className="mx-auto mb-5 w-fit rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-5 text-brand-300">
              <svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.4">
                <path d="M4.5 16.5 3 21l4.5-1.5M14.5 4.5c2.5-2.5 6-2.5 6-2.5s0 3.5-2.5 6L10 16l-3.5.5L6 13l8.5-8.5Z" />
                <path d="M9 15 6 12" />
                <circle cx="15" cy="9" r="1.2" />
              </svg>
            </div>
            <h2 className="text-xl font-bold">
              Launch your first <span className="grad-text">VPS</span>
            </h2>
            <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
              NVMe-backed KVM servers on a dedicated hypervisor, provisioned in under two minutes.
              Pick a plan, choose an OS, and you&apos;re live.
            </p>
            <Link href="/dashboard/deploy" className="btn-primary mt-6 px-8">
              Deploy your first server
            </Link>
          </div>
        </div>
      ) : (
        <>
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
            <StatCard label="Total servers" value={String(servers.length)} icon={icons.servers} href="/dashboard/servers" />
            <StatCard
              label="Running"
              value={`${running} / ${servers.length}`}
              icon={icons.running}
              href="/dashboard/servers"
            />
            <StatCard label="Monthly spend" value={fmtMoney(monthlySpendCents)} icon={icons.spend} href="/dashboard/billing" />
            <StatCard
              label="Wallet balance"
              value={fmtMoney(user.balanceCents)}
              delta="Add funds →"
              icon={icons.wallet}
              href="/dashboard/billing"
            />
          </div>

          <div className="card overflow-x-auto p-0">
            <div className="flex items-center justify-between px-4 pt-4">
              <p className="section-label">Servers</p>
              <Link href="/dashboard/servers" className="text-xs text-brand-300 hover:underline">
                View all →
              </Link>
            </div>
            <table className="table-shell mt-2 min-w-[680px]">
              <thead>
                <tr>
                  <th>Hostname</th>
                  <th>Status</th>
                  <th>Plan</th>
                  <th>Access</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {servers.map((s) => (
                  <tr key={s.id}>
                    <td>
                      <Link
                        href={`/dashboard/servers/${s.id}`}
                        className="font-semibold text-slate-100 hover:text-brand-300"
                      >
                        {s.hostname}
                      </Link>
                      {s.isFree && (
                        <span className="ml-2 align-middle">
                          <Badge tone="brand">free</Badge>
                        </span>
                      )}
                    </td>
                    <td>
                      <StatusDot status={s.status} />
                    </td>
                    <td className="text-slate-400">
                      {s.plan.name} · {s.plan.cpuCores} vCPU · {s.plan.ramMB / 1024} GB
                    </td>
                    <td className="font-mono text-xs text-slate-400">
                      {s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : "—"}
                    </td>
                    <td className="text-right">
                      <Link
                        href={`/dashboard/servers/${s.id}`}
                        className="btn-secondary px-3 py-1 text-xs"
                      >
                        Manage
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/*
            `grid-cols-1` is not cosmetic. Without an explicit base template this
            grid has no `grid-template-columns` under `lg`, so the browser creates
            an IMPLICIT `auto` track — and an implicit auto track is sized
            min-content, which the container cannot clamp. At 390px the rehearsal
            measured this single track resolving to 650.672px inside a 358px
            container (an unbreakable cuid in Recent activity sets the floor),
            giving the whole page 277px of horizontal scroll. `grid-cols-1`
            compiles to `repeat(1, minmax(0, 1fr))` — the same `minmax(0, …)` that
            `lg:grid-cols-2` already uses, which is exactly why the desktop layout
            never had this problem.
          */}
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <div className="card">
              <div className="mb-4 flex items-center justify-between">
                <p className="section-label">Recent activity</p>
                <Link href="/dashboard/activity" className="text-xs text-brand-300 hover:underline">
                  Full log →
                </Link>
              </div>
              {auditLogs.length === 0 ? (
                <p className="text-sm text-slate-400">No activity yet.</p>
              ) : (
                <ul className="space-y-3">
                  {auditLogs.map((log) => (
                    <li key={log.id} className="flex items-start gap-3 text-sm">
                      <span className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${actionDotColor(log.action)}`} />
                      <div className="min-w-0 flex-1">
                        <p className="text-slate-200">{humanizeAction(log.action)}</p>
                        {log.detail && (
                          <p className="truncate text-xs text-slate-500">{log.detail}</p>
                        )}
                      </div>
                      <span className="shrink-0 text-xs text-slate-500">{timeAgo(log.createdAt)}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>

            <div className="card">
              <div className="mb-4 flex items-center justify-between">
                <p className="section-label">Recent transactions</p>
                <Link href="/dashboard/billing" className="text-xs text-brand-300 hover:underline">
                  Billing →
                </Link>
              </div>
              {transactions.length === 0 ? (
                <p className="text-sm text-slate-400">No transactions yet.</p>
              ) : (
                <ul className="space-y-3">
                  {transactions.map((t) => (
                    <li key={t.id} className="flex items-center gap-3 text-sm">
                      <span className="min-w-0 flex-1 truncate text-slate-200">{t.description}</span>
                      <span
                        className={`shrink-0 font-mono text-xs ${
                          t.amountCents < 0 ? "text-red-400" : "text-emerald-400"
                        }`}
                      >
                        {t.amountCents < 0 ? "−" : "+"}
                        {fmtMoney(Math.abs(t.amountCents))}
                      </span>
                      <span className="shrink-0 text-xs text-slate-500">{timeAgo(t.createdAt)}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}
import { redirect } from "next/navigation";
import { currentUser, impersonating } from "@/lib/auth";
import { db } from "@/lib/db";
import { getSetting, getSettingBool } from "@/lib/settings";
import { Shell, type NavSection } from "@/components/portal/Shell";
import { UnverifiedEmailBanner } from "@/components/VerifyEmail";
import { isEmailVerified, isGrandfathered } from "@/lib/email-verification";
import { activeAnnouncementsForUser } from "@/lib/actions-broadcast";
import { AnnouncementBanner } from "@/components/customer/AnnouncementBanner";
import { PurchaseTracker } from "@/components/marketing/PurchaseTracker";
import { SignupTracker } from "@/components/marketing/SignupTracker";
import { PartnerSourceCapture } from "@/components/customer/PartnerSourceCapture";
import { HeardAboutUsPrompt } from "@/components/customer/HeardAboutUsPrompt";
import { CurrencyProvider } from "@/components/currency/CurrencyContext";
import { resolveDisplayCurrency } from "@/lib/currency-display";
import { AnnouncementPopup } from "@/components/customer/AnnouncementPopup";

/** Hrefs hidden from the customer nav when their feature flag is off. */
const FEATURE_HREF: Record<string, string> = {
  "/dashboard/games": "feature_game_servers",
  "/dashboard/claude-code": "feature_claude_builder",
  "/dashboard/build": "feature_claude_builder",
  "/dashboard/domains": "feature_domains",
  "/dashboard/refer": "feature_referrals",
  "/dashboard/affiliate": "feature_referrals",
  // Hidden by default until each is fully live: the website builder's publish path
  // is dormant (ENABLE_REAL_PUBLISH), and calendar is not shipped. Flip the setting
  // to true to reveal — the routes/code stay intact, this only gates the nav entry.
  "/dashboard/sites": "feature_website_builder",
  "/dashboard/calendar": "feature_calendar",
};

const nav: NavSection[] = [
  {
    items: [{ label: "Dashboard", href: "/dashboard", icon: "home" }],
  },
  {
    label: "Compute",
    items: [
      { label: "Deploy", href: "/dashboard/deploy", icon: "rocket" },
      { label: "Servers", href: "/dashboard/servers", icon: "server" },
      { label: "Shared Hosting", href: "/dashboard/hosting", icon: "globe" },
      { label: "Game Servers", href: "/dashboard/games", icon: "server", tag: "FREE" },
      { label: "Server Directory", href: "/game-servers/directory", icon: "globe" },
      { label: "Volumes", href: "/dashboard/volumes", icon: "db" },
    ],
  },
  {
    label: "Build",
    items: [
      { label: "Build with AI", href: "/dashboard/claude-code", icon: "sparkle" },
      { label: "Matrix", href: "/dashboard/build", icon: "bolt" },
    ],
  },
  {
    label: "Network",
    items: [
      { label: "Domains", href: "/dashboard/domains", icon: "globe" },
      { label: "Website builder", href: "/dashboard/sites", icon: "globe" },
      { label: "Calendar", href: "/dashboard/calendar", icon: "calendar" },
      { label: "SSL certificates", href: "/dashboard/ssl", icon: "shield" },
    ],
  },
  {
    // "Mail" groups the two easily-confused surfaces: Inbox is the actual webmail
    // reader (/dashboard/mail); Mailboxes is where you create and manage the email
    // accounts (/dashboard/email, formerly the ambiguous "Business email").
    label: "Mail",
    items: [
      { label: "Inbox", href: "/dashboard/mail", icon: "chat" },
      { label: "Mailboxes", href: "/dashboard/email", icon: "server" },
    ],
  },
  {
    label: "Tools",
    items: [
      { label: "Migration Center", href: "/dashboard/migrate", icon: "rocket" },
      { label: "Free tools", href: "/dashboard/tools", icon: "bolt" },
      { label: "What's New", href: "/dashboard/whats-new", icon: "sparkle" },
    ],
  },
  {
    label: "Account",
    items: [
      // Billing + Invoices merged (invoices live as a tab on the billing page);
      // Refer & earn + Affiliate merged; Support + Feedback merged.
      { label: "Billing", href: "/dashboard/billing", icon: "card" },
      { label: "Refer & earn", href: "/dashboard/refer", icon: "gift" },
      { label: "Partner Program", href: "/dashboard/partner", icon: "users" },
      { label: "Team", href: "/dashboard/team", icon: "users" },
      { label: "Support", href: "/dashboard/support", icon: "lifebuoy" },
      { label: "Activity", href: "/dashboard/activity", icon: "pulse" },
      { label: "Settings", href: "/dashboard/settings", icon: "cog" },
    ],
  },
];

export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) redirect("/login");
  const imp = await impersonating();

  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
  // admins impersonating a customer) always pass so they can keep working. This
  // only covers the dashboard tree — /login and /admin have their own layouts.
  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
    const message = await getSetting("maintenance_message");
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "1rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
      </main>
    );
  }

  // Hide nav entries whose feature flag is disabled (secondary to the server-side
  // refusals in the order/create actions).
  const flags: Record<string, boolean> = {
    feature_game_servers: await getSettingBool("feature_game_servers", true),
    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
    feature_domains: await getSettingBool("feature_domains", true),
    feature_referrals: await getSettingBool("feature_referrals", true),
    // Off by default — hidden until publishing / the feature is live (see FEATURE_HREF).
    feature_website_builder: await getSettingBool("feature_website_builder", false),
    feature_calendar: await getSettingBool("feature_calendar", false),
  };
  const visibleNav: NavSection[] = nav
    .map((section) => ({
      ...section,
      items: section.items.filter((item) => {
        const flag = FEATURE_HREF[item.href];
        return !flag || flags[flag];
      }),
    }))
    .filter((section) => section.items.length > 0);

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Support badge: this customer's own tickets awaiting a staff reply
  // (their newly opened tickets + threads where they replied last). Fails soft.
  const supportAwaiting = await db.ticket
    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
    .catch(() => 0);
  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
    ...section,
    items: section.items.map((item) =>
      item.href === "/dashboard/support" && supportAwaiting > 0
        ? { ...item, badge: supportAwaiting }
        : item
    ),
  }));

  // Provide the display-currency context to the portal so browse/catalog prices
  // can localize. DISPLAY ONLY: wallet balances, invoices and any actual CHARGE
  // amount must stay in USD and are NOT routed through this — see the boundary
  // note in lib/currency.ts. Only components that explicitly opt in via
  // `useDisplayMoney()` convert; nothing here is auto-converted.
  const { currency: displayCurrency, rates: fxRates } = await resolveDisplayCurrency();

  return (
    <CurrencyProvider initialCurrency={displayCurrency} rates={fxRates}>
    <Shell
      nav={navWithBadges}
      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
      impersonation={imp ? { adminName: imp.admin.name, targetEmail: imp.target.email } : null}
    >
      {/* Unverified accounts browse the whole portal freely; only buying is
          gated (lib/email-verification.ts). The prompt lives here rather than at
          checkout so the customer meets the prerequisite while it is cheap to
          fix, instead of meeting it with a card in their hand. Hidden while an
          admin is impersonating: it is not the admin's address to confirm, and
          the resend button would mail the customer from inside someone else's
          session. */}
      {!imp && !isEmailVerified(user) && !isGrandfathered(user) && (
        <UnverifiedEmailBanner email={user.email} />
      )}
      {/* Admin broadcasts — dismissible per-user. Soft-fails to nothing so a
          broadcast query problem can never take down the portal. */}
      <AnnouncementBanner announcements={await activeAnnouncementsForUser().catch(() => [])} />
      {/* Fires the Meta/Google Purchase conversion when a freshly-paid order lands on
          any dashboard route (fulfil-checkout tags the redirect). No-op otherwise. */}
      <PurchaseTracker />
      {/* Fires the "signup" conversion once when a freshly-registered account lands
          here (register() redirects to ?signup=1). Strips the marker; no-op otherwise. */}
      <SignupTracker />
      {/* Kodely (or any future partner) deep link (?ref=kodely) -> a short-lived
          cookie so payAndDeploy/purchaseDomain can attribute the order without
          threading the param through every wizard step. */}
      <PartnerSourceCapture />
      {/* One-time "How did you hear about us?" survey. Only when the account has
          not answered yet (heardAboutUs is null) and NOT while an admin is
          impersonating — the admin must never answer the survey on the
          customer's behalf. The server action is itself guarded to write only
          when null, so this is a UI gate over an idempotent write. */}
      {!imp && user.heardAboutUs == null && <HeardAboutUsPrompt />}
      {/* Update announcements popup — shows unseen service updates one at a
          time. Fetches client-side (no SSR delay) and soft-fails to nothing. */}
      <AnnouncementPopup />
      {children}
    </Shell>
    </CurrencyProvider>
  );
}
"use client";

import { ErrorState } from "@/components/ErrorState";

export default function DashboardError(props: { error: Error & { digest?: string }; reset: () => void }) {
  return <ErrorState {...props} context="dashboard" home="/dashboard" homeLabel="Back to dashboard" />;
}
export default function DashboardLoading() {
  return (
    <div className="space-y-6 p-1">
      <div className="h-8 w-52 animate-pulse rounded-lg bg-slate-800/60" />
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="h-28 animate-pulse rounded-xl bg-slate-800/40" />
        ))}
      </div>
      <div className="h-64 animate-pulse rounded-xl bg-slate-800/40" />
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { timeAgo } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import {
  ProfileForm,
  PasswordForm,
  AddSshKeyForm,
  DeleteSshKeyButton,
} from "@/components/customer/SettingsForms";
import { SecuritySettings } from "@/components/customer/SecuritySettings";
import { NotificationPrefs } from "@/components/customer/NotificationPrefs";
import { DangerZone } from "@/components/customer/DangerZone";
import { CloudflareIntegration } from "@/components/customer/CloudflareIntegration";
import { ClaudeKeyConnect } from "@/components/customer/ClaudeKeyConnect";
import { DiscordIntegration } from "@/components/admin/DiscordIntegration";
import { SignOutOthersButton } from "@/components/customer/AccountSecurityExtras";
import { normalizePrefs } from "@/lib/prefs";
import { getCloudflareStatus, cloudflareRedirectUri } from "@/lib/actions-cloudflare";
import { getDiscordLinkStatus } from "@/lib/actions-discord-link";

export const dynamic = "force-dynamic";

// Settings is organised into sub-tabs (server-rendered via ?tab=). "Integrations"
// groups the third-party connections — the customer's Anthropic (Claude) key and
// their Cloudflare connection — so credentials live in one obvious place.
const TABS = [
  { id: "profile", label: "Profile" },
  { id: "security", label: "Security" },
  { id: "integrations", label: "Integrations" },
  { id: "notifications", label: "Notifications" },
] as const;
type TabId = (typeof TABS)[number]["id"];

function shortKey(publicKey: string): string {
  const parts = publicKey.trim().split(/\s+/);
  const body = parts[1] ?? parts[0] ?? "";
  const type = parts[0] ?? "";
  if (body.length <= 40) return publicKey;
  return `${type} ${body.slice(0, 24)}…${body.slice(-12)}`;
}

