import { canAdministerOrg, verifyInviteToken } from "@/lib/team-guard";
import { PortalHero } from "@/components/portal/PortalHero";
import TeamInviteAccept from "@/components/customer/TeamInviteAccept";

export const dynamic = "force-dynamic";

/**
 * Landing page for the "Accept invitation" link in the team-invite email.
 *
 * This page only DESCRIBES the invitation — it never joins anyone. Joining
 * happens in `acceptInvite`, behind a button the invitee presses. That split is
 * the point of the whole change: an org membership must be an act by the
 * invitee, not a side effect of an email link being opened (or prefetched by a
 * mail client). Previously `inviteMember` created the membership on the
 * inviter's click alone.
 *
 * Signed-out visitors are bounced to /login by the dashboard layout. Someone
 * without an account yet registers first and then re-opens the emailed link;
 * the link stays valid for its full lifetime, so nothing is lost.
 */
export default async function AcceptInvitePage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string }>;
}) {
  const user = await requireUser();
  const { token } = await searchParams;

  const claims = await verifyInviteToken(String(token ?? ""));

  // Everything below decides only what to SHOW. Each check is repeated
  // server-side in `acceptInvite`, because a page render is not a permission.
  let problem: string | null = null;
  let orgName: string | null = null;
  let inviterName: string | null = null;

  if (!claims) {
    problem = "This invitation link is invalid or has expired. Ask the organization owner to send a new one.";
  } else if (claims.email !== user.email.trim().toLowerCase()) {
    // Don't name the org here: the signed-in account isn't the invitee, so it
    // isn't entitled to know which organization the link belongs to.
    problem = `This invitation was sent to a different email address. You're signed in as ${user.email} — sign in as the invited account to accept it.`;
  } else {
    const org = await db.organization.findUnique({
      where: { id: claims.orgId },
      select: { id: true, name: true },
    });
    const inviter = org
      ? await db.membership.findUnique({
          where: { orgId_userId: { orgId: org.id, userId: claims.invitedBy } },
          include: { user: { select: { name: true } } },
        })
      : null;
    if (!org) {
      problem = "That organization no longer exists.";
    } else if (!inviter || !canAdministerOrg(inviter.role)) {
      problem = "Whoever invited you no longer administers this organization, so the invitation is no longer valid.";
    } else {
      orgName = org.name;
      inviterName = inviter.user.name;
    }
  }

  return (
    <div className="space-y-6">
      <PortalHero variant="team" title="Team invitation" sub="Review the invitation before you join." />
      {problem || !claims || !orgName ? (
        <div className="card space-y-3">
          <p className="text-sm text-red-400">{problem ?? "This invitation can't be opened."}</p>
          <Link href="/dashboard/team" className="btn-ghost inline-flex px-3 py-1 text-xs">
            Back to Team
          </Link>
        </div>
      ) : (
        <TeamInviteAccept
          token={String(token)}
          orgName={orgName}
          inviterName={inviterName ?? "An organization admin"}
          role={claims.role}
        />
      )}
    </div>
  );
}
