/**
 * Server-side page guard. Redirects to /login if signed out, or back to the
 * overview if the (staff) user's role can't reach this area. Returns the real
 * signed-in user (impersonation is refused elsewhere in the admin layout).
 */
export async function requireArea(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  if (!canAccess(user.role, area)) redirect("/admin");
  return user;
}

"use client";

// Client-side currency context: holds the visitor's active DISPLAY currency + the
// FX rates table (both resolved on the server per-request and passed down through
// the layout), lets a manual switcher override the geo guess, and persists that
// override to a cookie so it survives navigation and reloads.
//
// DISPLAY ONLY. The formatter this exposes converts a USD-cents amount to a
// localized string; it never changes what a customer is charged. See the boundary
// note in lib/currency.ts.

import { createContext, useCallback, useContext, useMemo, useState } from "react";
import {
  CURRENCIES,
  CURRENCY_COOKIE,
  DEFAULT_CURRENCY,
  convertAndFormat,
  rateFor,
} from "@/lib/currency";

type CurrencyContextValue = {
  /** Active display currency code (always a key of CURRENCIES). */
  currency: string;
  /** Full rates table (target units per USD). */
  rates: Record<string, number>;
  /** The active currency's rate — > 0. */
  rate: number;
  /** Override the geo/default guess and persist it to a cookie. */
  setCurrency: (code: string) => void;
  /** Convert a USD-cents amount and format it in the active currency. */
  format: (baseUsdCents: number) => string;
};

const CurrencyContext = createContext<CurrencyContextValue | null>(null);

/** ~1 year, so a deliberate choice sticks. */
const COOKIE_MAX_AGE = 60 * 60 * 24 * 365;

export function CurrencyProvider({
  initialCurrency,
  rates,
  children,
}: {
  initialCurrency: string;
  rates: Record<string, number>;
  children: React.ReactNode;
}) {
  const normalizedInitial =
    initialCurrency && CURRENCIES[initialCurrency.toUpperCase()]
      ? initialCurrency.toUpperCase()
      : DEFAULT_CURRENCY;
  const [currency, setCurrencyState] = useState(normalizedInitial);

  const setCurrency = useCallback((code: string) => {
    const next = (code || "").toUpperCase();
    if (!CURRENCIES[next]) return;
    setCurrencyState(next);
    if (typeof document !== "undefined") {
      document.cookie = `${CURRENCY_COOKIE}=${next}; path=/; max-age=${COOKIE_MAX_AGE}; SameSite=Lax`;
    }
  }, []);

  const value = useMemo<CurrencyContextValue>(() => {
    const rate = rateFor(rates, currency);
    return {
      currency,
      rates,
      rate,
      setCurrency,
      format: (baseUsdCents: number) => convertAndFormat(baseUsdCents, currency, rate),
    };
  }, [currency, rates, setCurrency]);

  return <CurrencyContext.Provider value={value}>{children}</CurrencyContext.Provider>;
}

/**
 * Full currency context. Safe to call outside a provider — it degrades to a USD,
 * no-op formatter so a component rendered without the provider (e.g. in isolation)
 * still shows correct USD prices rather than throwing.
 */
export function useCurrency(): CurrencyContextValue {
  const ctx = useContext(CurrencyContext);
  if (ctx) return ctx;
  return {
    currency: DEFAULT_CURRENCY,
    rates: { USD: 1 },
    rate: 1,
    setCurrency: () => {},
    format: (baseUsdCents: number) => convertAndFormat(baseUsdCents, DEFAULT_CURRENCY, 1),
  };
}

/**
 * The price formatter alone: `const money = useDisplayMoney()` gives a
 * `(usdCents) => string` that converts to the visitor's active currency. Drop-in
 * for the local `money()` helpers each price component used to define.
 */
export function useDisplayMoney(): (baseUsdCents: number) => string {
  return useCurrency().format;
}
"use client";

// Searchable currency picker with flags. Reads/writes the shared currency context
// (persisted to a cookie), so choosing a currency re-formats every price that goes
// through useDisplayMoney() and sticks across navigation. DISPLAY ONLY — this
// changes how prices are shown, not what is charged.

import { useEffect, useMemo, useRef, useState } from "react";
import { CURRENCIES, currencyCountry } from "@/lib/currency";
import { useCurrency } from "./CurrencyContext";

// Most-used currencies float to the top; every other supported currency follows
// alphabetically, so ALL of them are reachable (via scroll or the search box).
const POPULAR = [
  "USD", "EUR", "GBP", "CAD", "AUD", "NZD", "CHF", "SEK", "NOK", "DKK", "PLN",
  "INR", "JPY", "CNY", "KRW", "SGD", "HKD", "AED", "SAR", "BRL", "MXN", "ZAR",
  "VND", "PHP", "THB", "IDR", "MYR", "TRY", "RUB",
];

/** A country flag, SELF-HOSTED under /public/flags (served from our own origin so
 *  it works everywhere — no external CDN that a region/ad-blocker might block, and
 *  the CSP 'self' always allows it). Renders a neutral chip if the flag is absent. */
function Flag({ code, size = 18 }: { code: string; size?: number }) {
  const cc = currencyCountry(code);
  const [ok, setOk] = useState(true);
  if (!ok || !cc) {
    return <span className="inline-block shrink-0 rounded-[2px] bg-white/10" style={{ width: size, height: Math.round(size * 0.75) }} aria-hidden />;
  }
  return (
    <img
      src={`/flags/${cc}.png`}
      width={size}
      height={Math.round(size * 0.75)}
      alt=""
      loading="lazy"
      onError={() => setOk(false)}
      className="shrink-0 rounded-[2px] object-cover"
    />
  );
}

export function CurrencySwitcher({ className = "" }: { className?: string }) {
  const { currency, setCurrency } = useCurrency();
  const [open, setOpen] = useState(false);
  const [dropUp, setDropUp] = useState(false);
  // Real bug found live: the panel is a fixed 256px wide, anchored via `right-0`
  // to the trigger — fine when the trigger sits near the viewport's right edge,
  // but on a narrow mobile layout where the trigger ends up further left (e.g.
  // the footer's stacked mobile column), `right-0` still extends the panel a
  // full 256px further left, pushing its left edge off-screen with no bounds
  // check at all (unlike `dropUp`, which already measures before deciding).
  // Same idea, horizontal axis: measure whether there's 256px of room to the
  // LEFT of the trigger's right edge; if not, anchor from the left instead.
  const [dropLeft, setDropLeft] = useState(false);
  const [query, setQuery] = useState("");
  const wrapRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  // Full currency names for display + search (e.g. "Vietnamese Dong"), native to
  // the platform — no data table to maintain. Falls back to the code if absent.
  const names = useMemo(() => {
    try {
      return new Intl.DisplayNames(["en"], { type: "currency" });
    } catch {
      return null;
    }
  }, []);
  const nameOf = (code: string) => {
    try {
      return names?.of(code) ?? code;
    } catch {
      return code;
    }
  };

  // Ordered list: popular first, then the rest A–Z.
  const allCodes = useMemo(() => {
    const pop = POPULAR.filter((c) => CURRENCIES[c]);
    const rest = Object.keys(CURRENCIES)
      .filter((c) => !pop.includes(c))
      .sort();
    return [...pop, ...rest];
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return allCodes;
    return allCodes.filter(
      (c) => c.toLowerCase().includes(q) || nameOf(c).toLowerCase().includes(q),
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query, allCodes]);

  // Close on outside click / Escape; focus the search when opening.
  useEffect(() => {
    if (!open) return;
    // Open upward when there isn't room below (e.g. the marketing footer), and
    // anchor from the left when there isn't 256px of room to the left of the
    // trigger's right edge (e.g. a mobile layout where this sits further left).
    const rect = wrapRef.current?.getBoundingClientRect();
    if (rect) {
      setDropUp(window.innerHeight - rect.bottom < 340);
      setDropLeft(rect.right < 256);
    }
    const onDown = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    document.addEventListener("mousedown", onDown);
    document.addEventListener("keydown", onKey);
    const t = setTimeout(() => searchRef.current?.focus(), 0);
    return () => {
      document.removeEventListener("mousedown", onDown);
      document.removeEventListener("keydown", onKey);
      clearTimeout(t);
    };
  }, [open]);

  function choose(code: string) {
    setCurrency(code);
    setOpen(false);
    setQuery("");
  }

  const meta = CURRENCIES[currency];

  return (
    <div ref={wrapRef} className={`relative ${className}`}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label="Display currency"
        className="inline-flex items-center gap-1.5 rounded-md border border-white/10 bg-navy-900/70 px-2 py-1 text-xs font-medium text-slate-200 outline-none transition-colors hover:border-white/25 focus:border-brand-500/60"
      >
        <Flag code={currency} size={16} />
        <span>{currency}</span>
        <span className="text-slate-500">{meta?.symbol.trim()}</span>
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden className="text-slate-500">
          <path d="M6 9l6 6 6-6" />
        </svg>
      </button>

      {open && (
        <div
          className={`absolute z-50 w-64 max-w-[calc(100vw-1.5rem)] overflow-hidden rounded-xl border border-white/10 bg-navy-950/95 shadow-2xl backdrop-blur-xl ${dropUp ? "bottom-full mb-1.5" : "mt-1.5"} ${dropLeft ? "left-0" : "right-0"}`}
        >
          <div className="border-b border-white/[0.06] p-2">
            <input
              ref={searchRef}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search currency…"
              className="w-full rounded-lg border border-white/10 bg-white/[0.04] px-3 py-1.5 text-xs text-slate-200 outline-none placeholder:text-slate-500 focus:border-brand-500/60"
            />
          </div>
          <ul role="listbox" className="max-h-72 overflow-y-auto py-1">
            {filtered.length === 0 && (
              <li className="px-3 py-4 text-center text-xs text-slate-500">No match</li>
            )}
            {filtered.map((c) => (
              <li key={c}>
                <button
                  type="button"
                  role="option"
                  aria-selected={c === currency}
                  onClick={() => choose(c)}
                  className={`flex w-full items-center gap-2.5 px-3 py-1.5 text-left text-xs transition-colors hover:bg-white/[0.06] ${
                    c === currency ? "bg-brand-500/15 text-white" : "text-slate-300"
                  }`}
                >
                  <Flag code={c} size={18} />
                  <span className="font-semibold">{c}</span>
                  <span className="truncate text-slate-500">{nameOf(c)}</span>
                  <span className="ml-auto shrink-0 text-slate-500">{CURRENCIES[c].symbol.trim()}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
// Server-side resolver for the visitor's DISPLAY currency + the active FX rates.
//
// This is the glue between the pure layers (lib/geo-currency.ts, the FX helpers in
// lib/tax.ts) and Next's request context (`headers()` / `cookies()`). Import it
// from server components / layouts only — it reads the Setting store (db).
//
// DISPLAY vs CHARGE: everything here decides only how prices are SHOWN. The charge
// currency is USD and is untouched. See the boundary note in lib/tax.ts.

import "server-only";
import { cookies, headers } from "next/headers";
import {
  CURRENCIES,
  CURRENCY_COOKIE,
  DEFAULT_CURRENCY,
  parseRatesOverride,
  rateFor,
} from "./currency";
import { getSetting } from "./settings";
import { countryFromHeaders, currencyForCountry } from "./geo-currency";
import { countryFromRequestIp } from "./geo-ip";

export { CURRENCY_COOKIE };

/** How the display currency was chosen — surfaced for debugging / the switcher UI. */
export type CurrencySource = "cookie" | "geo" | "default";

export type ResolvedCurrency = {
  /** The chosen DISPLAY currency code (always a key of CURRENCIES). */
  currency: string;
  /** Where the choice came from. */
  source: CurrencySource;
  /** Full rates table (target units per USD), admin-override merged over defaults. */
  rates: Record<string, number>;
  /** The chosen currency's rate — `rates[currency]`, guaranteed > 0. */
  rate: number;
};

/** Validate a code against the currencies we can actually render. */
function validCurrency(code: string | null | undefined): string | null {
  const c = (code ?? "").trim().toUpperCase();
  return c && CURRENCIES[c] ? c : null;
}

/** The active FX rates: the admin `currency_rates` override merged over defaults. */
export async function getCurrencyRates(): Promise<Record<string, number>> {
  return parseRatesOverride(await getSetting("currency_rates"));
}

/**
 * Resolve the visitor's display currency for the current request.
 *
 * Precedence:
 *   1. `nx_currency` cookie — an explicit manual choice from the switcher wins.
 *   2. CDN/proxy country header (Cloudflare `cf-ipcountry` etc.) → mapped currency.
 *   3. IP → country via the bundled geoip-lite dataset (works with no CDN in
 *      front; the header path in step 2 wins whenever a CDN is added later).
 *   4. The operator's configured default `currency` Setting (USD out of the box).
 *
 * Anything unrecognised at each step falls through to the next, and the final
 * fallback is always a currency we can render. Never throws.
 */
export async function resolveDisplayCurrency(): Promise<ResolvedCurrency> {
  const [jar, hdrs, rates, configuredDefault] = await Promise.all([
    cookies(),
    headers(),
    getCurrencyRates(),
    getSetting("currency"),
  ]);

  const fallback = validCurrency(configuredDefault) ?? DEFAULT_CURRENCY;

  let currency = fallback;
  let source: CurrencySource = "default";

  const cookieChoice = validCurrency(jar.get(CURRENCY_COOKIE)?.value);
  if (cookieChoice) {
    currency = cookieChoice;
    source = "cookie";
  } else {
    // CDN/proxy header first; else resolve the country from the client IP with
    // the local geoip-lite dataset (no CDN required). NB: countryFromHeaders
    // returns "" (not null) when absent, so use || — not ?? — to fall through.
    const country = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs);
    if (country) {
      const geoCurrency = validCurrency(currencyForCountry(country));
      // Only treat geo as decisive when it actually places the visitor somewhere
      // with a non-default currency; otherwise keep the operator default.
      if (geoCurrency && geoCurrency !== fallback) {
        currency = geoCurrency;
        source = "geo";
      } else if (geoCurrency) {
        source = "geo";
      }
    }
  }

  return { currency, source, rates, rate: rateFor(rates, currency) };
}
// Geo → display-currency inference. PURE and dependency-free (no db, no settings),
// so it is safe to import from the edge, server components, the client bundle and
// tests alike.
//
// SCOPE: this file only turns "which country is the visitor in" into "which
// currency code should we DISPLAY prices in". It performs NO FX conversion (that
// is lib/tax.ts + the rates table) and it never changes what a customer is
// CHARGED — the charge currency stays USD everywhere. See CURRENCY-DISPLAY note
