/** Normalise a country hint to an uppercase ISO-3166 alpha-2 code, or "". */
export function normalizeCountryCode(country: string | null | undefined): string {
  const c = (country ?? "").trim().toUpperCase();
  return /^[A-Z]{2}$/.test(c) ? c : "";
}

/**
 * Map a country to a DISPLAY currency code. Unknown / unmappable countries and
 * any mapping we cannot actually render both fall back to `DEFAULT_CURRENCY`
 * (USD). Never throws.
 */
export function currencyForCountry(country: string | null | undefined): string {
  const code = normalizeCountryCode(country);
  const cur = code ? COUNTRY_TO_CURRENCY[code] : undefined;
  return cur && CURRENCIES[cur] ? cur : DEFAULT_CURRENCY;
}

/** Anything with a `.get()`: `await headers()`, `req.headers`, or a `Request`. */
type HeaderLike = { get(name: string): string | null };

/**
 * Header names, in priority order, that a CDN / reverse proxy may use to attest
 * the visitor's country. `cf-ipcountry` is Cloudflare, `x-vercel-ip-country` is
 * Vercel's edge, and `x-nxeon-country` is a slot an operator can populate from
 * nginx (e.g. the GeoIP2 module: `proxy_set_header X-Nxeon-Country $geoip2_country;`)
 * if the platform is ever fronted by one. These headers are set by infrastructure
 * we control, not by the client — a browser cannot spoof `cf-ipcountry` past
 * Cloudflare. When none is present we return "" and the caller falls back to the
 * configured default currency + the manual switcher.
 */
export const COUNTRY_HEADERS = ["cf-ipcountry", "x-vercel-ip-country", "x-nxeon-country"] as const;

/** Read the visitor's country from CDN/proxy headers, or "" if none present. */
export function countryFromHeaders(source: HeaderLike | { headers: HeaderLike }): string {
  const h: HeaderLike =
    typeof (source as HeaderLike)?.get === "function"
      ? (source as HeaderLike)
      : (source as { headers: HeaderLike }).headers;
  for (const name of COUNTRY_HEADERS) {
    const v = normalizeCountryCode(h.get(name));
    // "XX"/"T1" are Cloudflare placeholders for unknown/Tor — treated as absent.
    if (v && v !== "XX" && v !== "T1") return v;
  }
  return "";
}
// Pure currency primitives — symbols, formatting, and DISPLAY-ONLY FX conversion.
//
// This module has NO server dependencies (no db, no settings, no "server-only"),
// so it is safe to import from client components, the edge, server components and
// tests alike. lib/tax.ts re-exports everything here, so existing `@/lib/tax`
// import sites keep working unchanged — the split exists purely so a "use client"
// price component can format money without dragging the Setting store (and Prisma)
// into the browser bundle.
//
// ─────────────────────────────────────────────────────────────────────────────
// DISPLAY vs CHARGE BOUNDARY — the load-bearing invariant of this whole layer.
// ─────────────────────────────────────────────────────────────────────────────
// Prices are stored as integer USD cents and USD is the CHARGE currency: every
// invoice, top-up, wallet balance and provider/registrar cost is denominated and
// settled in USD, and NONE of that is touched here. The helpers below take a
// USD-cents amount and produce a *DISPLAYED* string in a visitor's local currency
// using a configurable rates table — so a euro visitor sees "€4.60" where a US
// visitor sees "$5.00", but both are billed the same $5.00. This is a storefront
// convenience, not multi-currency billing. NEVER feed a converted amount back
// into a charge path.

export type CurrencyMeta = { symbol: string; code: string };

