function Icon({ name }: { name: string }) {
  return (
    <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
      {icons[name] ?? icons.folder}
    </svg>
  );
}

function Logo({ tag, collapsed }: { tag?: string; collapsed?: boolean }) {
  return (
    <Link href="/" className={`flex items-center gap-2.5 px-2 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/logo.png"
        alt="Nxeon"
        style={{ height: 40, width: "auto" }}
        className={`select-none object-contain ${collapsed ? "lg:hidden" : ""}`}
      />
      {/* Compact mark, shown only when the desktop rail is collapsed. */}
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src="/icon-192.png"
        alt="Nxeon"
        style={{ height: 30, width: 30 }}
        className={`hidden select-none object-contain ${collapsed ? "lg:block" : ""}`}
      />
      {tag && (
        <span
          className={`rounded-md border border-amber-400/30 bg-amber-400/10 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-widest text-amber-300 ${
            collapsed ? "lg:hidden" : ""
          }`}
        >
          {tag}
        </span>
      )}
    </Link>
  );
}

export function Shell({
  nav,
  user,
  notifications,
  impersonation,
  tag,
  indicatorAccess,
  children,
}: {
  nav: NavSection[];
  user: { name: string; email: string; role: string; balanceCents: number };
  notifications: ShellNotification[];
  impersonation?: { adminName: string; targetEmail: string } | null;
  tag?: string;
  /** Which floating attention bubbles this account can actually use — see
   *  AdminIndicators' own doc comment. Both default true (the admin portal
   *  never passes this; ADMIN always has full access). app/staff/layout.tsx
   *  computes these from the EMPLOYEE's real StaffGrants. */
  indicatorAccess?: { support?: boolean; inbox?: boolean };
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  // Which portal is this Shell rendering? The admin ops layout passes tag="ops",
  // the new employee portal (app/staff/layout.tsx) passes tag="staff", and the
  // customer dashboard passes none. This drives which floating widgets mount:
  // the customer portal keeps the Feedback bubble (and the live-chat bubble from
  // the root layout), while both staff-facing portals swap them for the
  // support + email attention indicators. (Role is NOT a reliable signal here —
  // an ADMIN visiting /dashboard is still on the customer portal, and an ADMIN
  // previewing /staff is still on the employee portal.)
  const isAdminPortal = tag === "ops";
  const isStaffPortal = tag === "staff";
  // Full-bleed routes (the mail + calendar apps) opt out of the centered/padded
  // main so they fill the entire content area under the header with no gap.
  // /staff/inbox mirrors /admin/inbox (same underlying mail view, Phase 5).
  const fullBleed =
    pathname === "/dashboard/mail" ||
    pathname === "/dashboard/calendar" ||
    pathname === "/admin/inbox" ||
    pathname === "/admin/board" ||
    pathname === "/admin/reddit" ||
    pathname === "/staff/inbox" ||
    pathname === "/staff/reddit";
  // Wide (but still centered/padded, unlike fullBleed) routes — data-table-heavy
  // pages that were clipping real columns (Time on page/Account/Referrer) at
  // the standard 1280px cap. Keeps the page's own section padding/spacing
  // (fullBleed strips that entirely, which this page still relies on for its
  // stacked stat-card/globe/table sections) while giving the traffic feed
  // table room to actually show its columns instead of truncating them.
  const wideContent = pathname === "/admin/visitors";
  const [notifOpen, setNotifOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  // Desktop-only main-sidebar collapse. Persisted so it holds across every
  // portal page (mail, calendar, servers…). On mobile the drawer always renders
  // expanded — every collapse style below is gated to the `lg:` breakpoint.
  const [collapsed, setCollapsed] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    try {
      if (localStorage.getItem("nxeon.portal.railCollapsed") === "1") setCollapsed(true);
    } catch {}
  }, []);
  function toggleCollapsed() {
    setCollapsed((c) => {
      const next = !c;
      try {
        localStorage.setItem("nxeon.portal.railCollapsed", next ? "1" : "0");
      } catch {}
      return next;
    });
  }

  /**
   * Per-group collapse (admin portal only). Sits alongside the whole-rail
   * collapse above but tracks each nav SECTION independently, keyed by
   * `section.key` — a map of collapsed group keys to `true`, everything absent
   * defaults to expanded so a first-time admin (or the customer portal, which
   * never toggles this) sees exactly the same sidebar as before this existed.
   * Mirrors the rail-collapse persistence pattern: hydrate once on mount,
   * write back on every toggle, both wrapped in try/catch so a blocked or
   * full localStorage never breaks navigation.
   */
  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>({});
  useEffect(() => {
    try {
      const raw = localStorage.getItem("nxeon.admin.navCollapsed");
      if (raw) setCollapsedGroups(JSON.parse(raw));
    } catch {}
  }, []);
  function toggleGroup(key: string) {
    setCollapsedGroups((prev) => {
      const next = { ...prev, [key]: !prev[key] };
      try {
        localStorage.setItem("nxeon.admin.navCollapsed", JSON.stringify(next));
      } catch {}
      return next;
    });
  }

  /**
   * Publish the rail's current width so `position: fixed` chrome outside this
   * subtree can sit beside it instead of guessing.
   *
   * The terminal dock hardcoded `lg:left-60` (15rem) while the rail collapses to
   * `lg:w-[4.75rem]`, leaving a ~10rem dead gutter down the left of the terminal
   * whenever a customer collapsed the sidebar. A CSS variable on the document
   * element reaches the dock regardless of where it is mounted.
   */
  useEffect(() => {
    document.documentElement.style.setProperty("--nx-rail-w", collapsed ? "4.75rem" : "15rem");
  }, [collapsed]);

  /**
   * Is the mobile drawer currently a drawer at all? Below `lg` the rail is an
   * off-canvas panel translated out of view; at `lg` and up it is the ordinary
   * page sidebar and must never be hidden or inerted.
   *
   * Starts `true` (desktop) so the server render and the first client render
   * agree, and so a JS-less or pre-hydration page never has its navigation
   * inerted. The listener corrects it a tick later.
   */
  const [isDesktopRail, setIsDesktopRail] = useState(true);
  useEffect(() => {
    const mq = window.matchMedia("(min-width: 1024px)");
    const sync = () => setIsDesktopRail(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  /**
   * Closed, off-canvas and out of reach. The rehearsal found the closed drawer
   * still `visibility: visible` with no `aria-hidden` and **25 focusable
   * descendants in the tab order** — so a keyboard user on a phone tabbed
   * through the entire hidden navigation before reaching the page.
   */
  const drawerHidden = !isDesktopRail && !sidebarOpen;

  // Escape closes the drawer. It did nothing at all before: the drawer had no
  // close button either (the only in-drawer button is the collapse toggle, which
  // is `lg:flex`), so a backdrop tap was the single way out.
  useEffect(() => {
    if (!sidebarOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSidebarOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [sidebarOpen]);

  // Navigating from a drawer link must close the drawer — otherwise the new page
  // renders behind a panel the customer has to dismiss by hand.
  useEffect(() => {
    setSidebarOpen(false);
  }, [pathname]);

  // Opening the bell marks everything read server-side, but `notifications` is a
  // prop rendered from the initial server load, so without this the blue count
  // and the bold titles would stay lit for the rest of the session even though
  // the server now considers them read — a "you have unread mail" badge that
  // won't clear. Track the open-and-marked edge locally and reconcile the view
  // to it. Once marked, unread is 0 and nothing renders as unread.
  const [notifMarked, setNotifMarked] = useState(false);
  // The optimistic clear only covers the window between opening the bell and the
  // server revalidating. Once a fresh `notifications` prop arrives (e.g. a new
  // notification, or the read state confirmed), drop the optimism so a genuinely
  // new unread item still lights the badge.
  useEffect(() => {
    setNotifMarked(false);
  }, [notifications]);
  const unread = notifMarked ? 0 : notifications.filter((n) => !n.readAt).length;

  // Live unread-INBOX count for the "Inbox" nav badge. Polled client-side because
  // IMAP is far too slow to run on every server-side layout render. Only polls when
  // the portal actually has a Mail entry; fails soft to no badge.
  const hasMailNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/mail"));
  const [mailUnread, setMailUnread] = useState(0);
  useEffect(() => {
    if (!hasMailNav) return;
    let alive = true;
    const load = () =>
      fetch("/api/mail/unread")
        .then((r) => (r.ok ? r.json() : { unread: 0 }))
        .then((d) => alive && setMailUnread(Number(d?.unread) || 0))
        .catch(() => {});
    load();
    const id = setInterval(load, 60_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [hasMailNav]);

  // Live Matrix status for the "Matrix" nav tag. Polls the user's own console
  // builds: shows "running" while a build is in flight, and "update" when one
  // has reached a state worth a look (finished, or a plan awaiting approval)
  // that the customer hasn't seen since they last opened the workspace. Only
  // polls when the portal has a Matrix entry; fails soft to no tag.
  const hasMatrixNav = nav.some((s) => s.items.some((i) => i.href === "/dashboard/build"));
  const [matrixStatus, setMatrixStatus] = useState<{
    running: number;
    needsAttention: number;
    lastEventAt: string | null;
  }>({ running: 0, needsAttention: 0, lastEventAt: null });
  // Timestamp (ms) the customer last "saw" Matrix. Seeded to now on first ever
  // load so pre-existing finished builds don't light a stale "update" tag —
  // only events from here forward count. Bumped whenever they open the workspace.
  const [matrixSeenAt, setMatrixSeenAt] = useState<number>(0);
  useEffect(() => {
    try {
      const v = localStorage.getItem("nxeon.matrix.seenAt");
      if (v) {
        setMatrixSeenAt(Number(v) || 0);
      } else {
        const now = Date.now();
        setMatrixSeenAt(now);
        localStorage.setItem("nxeon.matrix.seenAt", String(now));
      }
    } catch {
      setMatrixSeenAt(Date.now());
    }
  }, []);
  useEffect(() => {
    if (!hasMatrixNav) return;
    let alive = true;
    const load = () =>
      fetch("/api/claude/console-status")
        .then((r) => (r.ok ? r.json() : null))
        .then((d) => {
          if (alive && d) {
            setMatrixStatus({
              running: Number(d.running) || 0,
              needsAttention: Number(d.needsAttention) || 0,
              lastEventAt: d.lastEventAt ?? null,
            });
          }
        })
        .catch(() => {});
    load();
    const id = setInterval(load, 20_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, [hasMatrixNav]);
  // Opening the workspace marks everything seen (clears the "update" tag). Also
  // re-marks if a fresh event lands while they're already on the page.
  useEffect(() => {
    if (pathname !== "/dashboard/build") return;
    const now = Date.now();
    setMatrixSeenAt(now);
    try {
      localStorage.setItem("nxeon.matrix.seenAt", String(now));
    } catch {}
  }, [pathname, matrixStatus.lastEventAt]);
  const matrixTag: "running" | "update" | null =
    matrixStatus.running > 0
      ? "running"
      : matrixStatus.lastEventAt != null && Date.parse(matrixStatus.lastEventAt) > matrixSeenAt
        ? "update"
        : null;

  // Escape closes the notifications dropdown too (it only closed the drawer
  // before), matching the palette and drawer. A click anywhere else dismisses it
  // via the click-away layer rendered below.
  useEffect(() => {
    if (!notifOpen) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setNotifOpen(false);
    };
    window.addEventListener("keydown", onKey);

    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [notifOpen]);

  // Flatten for the command palette: every sidebar entry plus every secondary
  // destination hidden behind it, so ⌘K still reaches all ~41 admin routes even
  // though only 14 of them have a sidebar row. The child sharing the entry's own
  // href is skipped so the landing page isn't listed twice. Flat items (customer
  // portal) pass through unchanged.
  const flatNav = nav.flatMap((s) =>
    s.items.flatMap((i) => [
      { label: i.label, href: i.href, section: s.label },
      ...(i.children ?? [])
        .filter((c) => c.href !== i.href)
        .map((c) => ({ label: c.label, href: c.href, section: s.label })),
    ])
  );

  return (
    // The terminal dock lives at the shell level so a shell session survives
    // in-portal navigation: App Router keeps Shell mounted across page changes,
    // so the dock (and its live sockets) is never unmounted. The provider is
    // inert until a page calls useTerminalDock().openSession(...).
    <TerminalDockProvider>
    {/* The compose provider lives at the shell level for the same reason as the
        terminal dock: App Router keeps Shell mounted across in-portal navigation,
        so an open (or minimized) mail composer — and its in-progress draft —
        survives moving between dashboard pages. It renders the composer through a
        portal to <body> and is inert until a mail page calls useCompose().open(). */}
    <ComposeProvider>
    {/* The Matrix workspace lives at the shell level for the same reason as the
        terminal dock and compose provider: App Router keeps Shell mounted across
        in-portal navigation, so open build consoles and their live server
        terminals survive moving between pages. It is lazy (nothing until the
        customer first opens Matrix) and inert on every non-customer route. */}
    <MatrixProvider>
    <div className="flex min-h-screen">
      <CommandPalette nav={flatNav} />
      {/* Customer portal: the Feedback bubble (+ the live-chat bubble mounted by
          the root layout). Admin ops portal: staff-facing support + email
          attention indicators instead (the customer widgets are suppressed on
          /admin). */}
      {isAdminPortal || isStaffPortal ? (
        <AdminIndicators
          isStaffPortal={isStaffPortal}
          showSupport={indicatorAccess?.support ?? true}
          showInbox={indicatorAccess?.inbox ?? true}
        />
      ) : (
        <FeedbackWidget />
      )}
      <VisitTracker kind="portal" />

      {/* Sidebar */}
      <aside
        id="portal-sidebar"
        // `lg:sticky lg:top-0 lg:h-screen`, NOT `lg:static`: static put the rail in
        // normal document flow, so on desktop it scrolled away with the page and
        // navigation disappeared on any long view. Sticky keeps it in flow (main
        // content still sits beside it, no overlap) while pinning it to the
        // viewport. The <nav> inside already has flex-1 + overflow-y-auto, so a
        // long menu scrolls within the rail rather than pushing it off-screen.
        className={`fixed inset-y-0 left-0 z-40 flex w-60 flex-col border-r border-white/[0.06] bg-navy-900/80 backdrop-blur-xl transition-all lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${
          collapsed ? "lg:w-[4.75rem]" : "lg:w-60"
        } ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}
        // Off-canvas and closed on a phone: out of the tab order and out of the
        // accessibility tree. `-translate-x-full` alone hides it from eyes only —
        // 25 links behind it stayed focusable.
        inert={drawerHidden}
        aria-hidden={drawerHidden || undefined}
      >
        <div className={`flex h-16 items-center px-4 ${collapsed ? "lg:justify-center lg:px-0" : ""}`}>
          <Logo tag={tag} collapsed={collapsed} />
          {/*
            The drawer had no way to close itself — the only in-drawer button is
            the collapse toggle, and that is `lg:flex`. Escape works now too, but
            a visible control is what most people reach for.
          */}
          <button
            type="button"
            className="btn-ghost ml-auto rounded-lg p-2 lg:hidden"
            aria-label="Close menu"
            onClick={() => setSidebarOpen(false)}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M6 6l12 12M18 6 6 18" />
            </svg>
          </button>
        </div>
        <nav className={`flex-1 space-y-5 overflow-y-auto px-3 pb-6 pt-2 ${collapsed ? "lg:px-2" : ""}`}>
          {nav.map((section, si) => {
            const groupKey = section.key ?? String(si);
            // Only the admin ops portal gets collapsible groups — the customer
            // portal keeps its section headers as plain, unclickable labels.
            const groupCollapsible = (isAdminPortal || isStaffPortal) && !!section.label;
            const groupCollapsed = groupCollapsible && !!collapsedGroups[groupKey];
            // While the whole rail is collapsed to icons, a group's own
            // collapsed state is moot (there's no header to click to re-expand
            // it) — always show every icon row so nothing becomes unreachable.
            const hideItems = groupCollapsed && !collapsed;
            // Sum every item's badge in this group so a notification inside a
            // collapsed group is never invisible — shown only while collapsed;
            // once expanded, each item already shows its own count.
            const groupBadgeTotal = section.items.reduce((sum, item) => sum + (item.badge ?? 0), 0);
            return (
            <div key={si}>
              {section.label && (
                groupCollapsible ? (
                  <button
                    type="button"
                    onClick={() => toggleGroup(groupKey)}
                    aria-expanded={!groupCollapsed}
                    className={`section-label mb-2 flex w-full items-center justify-between rounded-md px-3 py-0.5 text-left transition-colors hover:text-slate-300 ${
                      collapsed ? "lg:hidden" : ""
                    }`}
                  >
                    <span className="flex items-center gap-1.5">
                      {section.label}
                      {groupCollapsed && groupBadgeTotal > 0 && (
                        <span className="inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-violet-500 px-1 text-[10px] font-semibold leading-none text-white">
                          {groupBadgeTotal > 99 ? "99+" : groupBadgeTotal}
                        </span>
                      )}
                    </span>
                    <svg
                      width="10"
                      height="10"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="3"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      className={`shrink-0 transition-transform ${groupCollapsed ? "-rotate-90" : ""}`}
                    >
                      <path d="M6 9l6 6 6-6" />
                    </svg>
                  </button>
                ) : (
                  <p className={`section-label mb-2 px-3 ${collapsed ? "lg:hidden" : ""}`}>{section.label}</p>
                )
              )}
