import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

/**
 * Global portal search, powering the ⌘K palette / top-bar "Search anything".
 *
 * Searches across everything a caller can reach — servers, hosting plans,
 * hosting accounts, websites, mailboxes (email), domains and tickets — plus, for
 * admins, customers. Every result carries a `type` (for grouping + an icon) and a
 * ready-to-navigate `href` that jumps straight to the item.
 *
 * SCOPING is the security boundary and is applied per model:
 *   • Customers see ONLY their own rows (`userId` / relation scoped).
 *   • Admins see ACROSS accounts, and their result links point at the /admin
 *     equivalents.
 * Catalog rows (hosting plans) are the one non-owned type: everyone may see the
 * active plans; admins additionally see inactive ones.
 *
 * The response is `private, no-store` because for an admin it contains other
 * customers' hostnames, emails and ticket subjects — a shared cache keyed on the
 * `?q=` URL would otherwise replay one caller's results to the next.
 */
export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ results: [] }, { status: 401, headers: NO_STORE_HEADERS });
  }
  const q = (req.nextUrl.searchParams.get("q") ?? "").trim();
  if (q.length < 2) return NextResponse.json({ results: [] }, { headers: NO_STORE_HEADERS });

  const isAdmin = user.role === "ADMIN";
  // Ownership filter reused across every customer-owned model.
  const own = isAdmin ? {} : { userId: user.id };
  const like = { contains: q, mode: "insensitive" as const };

  const results: { type: string; label: string; sub?: string; href: string }[] = [];

  // Everything runs concurrently; each block fails soft so one bad table can't
  // blank the whole palette.
  const soft = <T,>(p: Promise<T>, fallback: T): Promise<T> => p.catch(() => fallback);

  const [servers, plans, accounts, websites, mailboxes, domains, tickets, customers] =
    await Promise.all([
      // Servers (VPS + game). Match the hostname, the customer nickname, or the name.
      soft(
        db.server.findMany({
          where: { OR: [{ hostname: like }, { label: like }, { name: like }], ...own },
          include: { user: true },
          take: 6,
        }),
        [] as Array<{
          id: string;
          hostname: string;
