              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
              </svg>
            </span>
            <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
              What&apos;s new
            </span>
          </div>
          <h2
            id="announcement-title"
            className="mt-2 text-lg font-bold tracking-tight text-white"
          >
            {current.title}
          </h2>
          {current.serviceTypes.length > 0 && (
            <div className="mt-1.5 flex gap-1.5">
              {current.serviceTypes.map((t) => (
                <span
                  key={t}
                  className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                >
                  {t}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Body */}
        <div className="max-h-[60vh] overflow-y-auto px-6 py-5">
          {current.gameFamilies.length > 0 && (
            <div className="mb-4">
              <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-slate-500">
                {current.gameFamilies.length > 1 ? "Games covered in this update" : "Game"}
              </p>
              <div className={`grid gap-2 ${current.gameFamilies.length === 1 ? "grid-cols-3" : "grid-cols-4 sm:grid-cols-5"}`}>
                {current.gameFamilies.map((g) => (
                  <div key={g} className="overflow-hidden rounded-lg border border-white/10">
                    <GameCoverTile family={g} name={GAME_DISPLAY[g as GameFamily]?.name ?? g} />
                    <p className="truncate bg-black/40 px-1.5 py-1 text-center text-[10px] font-medium text-slate-200">
                      {GAME_DISPLAY[g as GameFamily]?.name ?? g}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
          <div
            dangerouslySetInnerHTML={{ __html: renderMarkdown(current.body) }}
          />
          {current.screenshotUrl && (
            <div className="mt-4">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={current.screenshotUrl}
