import { useState, useTransition } from "react";
import { createPortal } from "react-dom";
// Namespace import (never named): a computed key lookup can't produce an
// "export not found" build error, so an unknown/removed brand simply renders
// nothing and the button falls back to its plain label. Same pattern as
// components/marketing/CompetitorLogo.tsx.
import * as simpleIcons from "simple-icons";
import { IconUsers } from "@/components/marketing/icons";
import { setHeardAboutUs } from "@/lib/actions-account";
import { HEARD_OPTIONS, HEARD_OTHER_MAX } from "@/lib/heard-about";

type SimpleIcon = { title: string; slug: string; hex: string; path: string };

/** Channel key → Simple Icons export name, for the real platforms we can
 *  scrape an accurate vector brand mark for. `color` overrides the brand's
 *  own hex only when that hex is near-black (TikTok, X) and would otherwise
 *  vanish on this modal's dark card background. */
const HEARD_BRAND_ICON: Record<string, { key: string; color?: string }> = {
  google: { key: "siGoogle" },
  youtube: { key: "siYoutube" },
  instagram: { key: "siInstagram" },
  tiktok: { key: "siTiktok", color: "#FFFFFF" },
  facebook: { key: "siFacebook" },
  x: { key: "siX", color: "#FFFFFF" },
  reddit: { key: "siReddit" },
  // simple-icons has no separate "ChatGPT" mark — OpenAI's is the closest real
  // brand icon (same relationship as a customer saying "ChatGPT" to mean the
  // OpenAI product). Label stays "ChatGPT" (lib/heard-about.ts); only the icon
  // is OpenAI's.
  chatgpt: { key: "siOpenai" },
};

/** Real vector brand mark for a platform channel, or null when the key isn't
 *  one of the platforms above (the non-platform options use hand-drawn line
 *  icons instead — see below). */
function BrandIcon({ channelKey, size = 22 }: { channelKey: string; size?: number }) {
  const entry = HEARD_BRAND_ICON[channelKey];
  const icon = entry ? ((simpleIcons as Record<string, unknown>)[entry.key] as SimpleIcon | undefined) : undefined;
  if (!icon || typeof icon.path !== "string") return null;
  return (
    <svg role="img" aria-hidden viewBox="0 0 24 24" style={{ height: size, width: size }}>
      <path d={icon.path} fill={entry?.color ?? `#${icon.hex}`} />
    </svg>
  );
}

/** Shared stroke style for the non-platform line icons below — same visual
 *  language as components/marketing/icons.tsx and PaymentStep.tsx's inline
 *  icons (24×24, stroke=currentColor), so they inherit the button's text
 *  color and adapt to the selected state automatically. */
function LineIcon({ size = 22, children }: { size?: number; children: React.ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.7"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
    >
      {children}
    </svg>
  );
}

function OtherIcon(p: { size?: number }) {
  return (
    <LineIcon {...p}>
      <circle cx="12" cy="12" r="9" />
      <path d="M9.4 9.2a2.6 2.6 0 1 1 3.7 2.35c-.85.4-1.1.95-1.1 1.75" />
      <circle cx="12" cy="16.9" r="0.9" fill="currentColor" stroke="none" />
    </LineIcon>
  );
}

/** Icon for a HEARD_OPTIONS key (or "other"): the real brand mark for a
 *  platform, a matching line icon for the non-platform options, or null. */
function optionIcon(key: string): React.ReactNode {
  if (HEARD_BRAND_ICON[key]) return <BrandIcon channelKey={key} />;
  if (key === "friend") return <IconUsers size={22} />;
  if (key === "other") return <OtherIcon />;
  return null;
}

/**
 * One-time "How did you hear about us?" acquisition survey.
 *
 * Rendered from the dashboard layout ONLY when the signed-in customer's
 * `heardAboutUs` is still null and no admin is impersonating them. The layout's
 * server-side null check is the real gate — this component just shows the modal
 * once and then closes for good. The write itself is idempotent
 * (setHeardAboutUs only sets when null), so even a double-submit is safe.
 *
 * The overlay is portaled to document.body: the portal (Shell) wraps content in
 * transformed ancestors, and a `position: fixed` node inside a transformed
 * parent anchors to THAT parent, not the viewport — dropping the modal down the
 * page. Same fix as components/admin/EmailLogViewer.tsx.
 */
export function HeardAboutUsPrompt() {
  // Local visibility. Starts open because the parent only mounts us when the
  // server says heardAboutUs is null; once dismissed it never comes back this
  // session, and the null→value transition keeps it gone on future loads.
  const [open, setOpen] = useState(true);
  const [choice, setChoice] = useState<string | null>(null);
  const [otherText, setOtherText] = useState("");
  const [pending, startTransition] = useTransition();

  if (!open) return null;
  if (typeof document === "undefined") return null;

  const submit = (source: string) => {
    // Close optimistically — the answer is fire-and-forget and the server is the
    // source of truth for "asked once", so we never need to reopen on failure.
    setOpen(false);
    startTransition(async () => {
      try {
        await setHeardAboutUs(source);
      } catch {
        /* best-effort: a failed survey write must never surface an error */
      }
    });
  };

  const answer = () => {
    if (!choice) return;
    if (choice === "other") {
      const text = otherText.trim();
      submit(text ? `other:${text}` : "other");
    } else {
      submit(choice);
    }
  };

  const canSubmit = choice !== null && (choice !== "other" || otherText.trim().length > 0);

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="heard-title"
    >
      <div className="card w-full max-w-lg p-6 motion-safe:animate-panel-in" onClick={(e) => e.stopPropagation()}>
        <h2 id="heard-title" className="text-lg font-bold tracking-tight">
          How did you hear about us?
        </h2>
        <p className="mt-1 text-sm text-slate-400">
          Quick one-tap question — it helps us reach more people like you. This won&apos;t be asked again.
        </p>

        <div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-3">
          {HEARD_OPTIONS.map((o) => (
            <button
              key={o.key}
              type="button"
              onClick={() => setChoice(o.key)}
              aria-pressed={choice === o.key}
              className={`flex flex-col items-center gap-1.5 rounded-xl border px-3 py-3 text-sm font-medium transition-colors ${
                choice === o.key
                  ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                  : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
              }`}
            >
              {optionIcon(o.key)}
              <span>{o.label}</span>
            </button>
          ))}
          <button
            type="button"
            onClick={() => setChoice("other")}
            aria-pressed={choice === "other"}
            className={`flex flex-col items-center gap-1.5 rounded-xl border px-3 py-3 text-sm font-medium transition-colors ${
              choice === "other"
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
            }`}

